@php
    $openInvoiceCount = $invoices->filter(fn ($invoice) => (float) $invoice->open_amount > 0)->count();
    $nearestExpiry = $contracts->where('status', 'ACTIVE')->whereNotNull('ends_on')->sortBy('ends_on')->first()?->ends_on?->format('d M Y') ?? '—';
    $sectionItems = ['requests'=>['requests','Service Requests'], 'work-orders'=>['work-orders','Work Orders'], 'visits'=>['visits','Visits & Schedule'], 'maintenance'=>['maintenance','Maintenance Plan'], 'spare-parts'=>['parts','Spare Parts'], 'sites'=>['sites','Sites'], 'assets'=>['assets','Assets & Equipment'], 'quotations'=>['quotations','Quotations'], 'contracts'=>['contracts','Contracts'], 'sla'=>['sla','SLA & KPIs'], 'invoices'=>['invoices','Invoices & Payments'], 'reports'=>['reports','Reports'], 'documents'=>['documents','Document Library'], 'timeline'=>['activity','Recent Activity'], 'notifications'=>['notifications','Notifications']];
    $groups = ['Overview'=>['dashboard'],'My Work'=>['requests','work-orders','visits','maintenance','spare-parts'],'Sites & Assets'=>['sites','assets'],'Commercial & Contracts'=>['quotations','contracts','sla'],'Finance'=>['invoices'],'Reports & Records'=>['reports','documents','timeline','notifications']];
    $badges = ['requests'=>$openRequestCount,'work-orders'=>$openWorkOrders,'visits'=>$visitsDue7Count,'quotations'=>$pendingQuotationCount,'invoices'=>$invoiceActionCount,'notifications'=>$alerts->count()];
    $requestSegments = [['New',$requestStageCounts['new'],'#1682df'],['Under review',$requestStageCounts['review'],'#8b5cf6'],['Assigned',$requestStageCounts['assigned'],'#33a3f4'],['In progress',$requestStageCounts['progress'],'#f4a51c'],['Team dispatched',$requestStageCounts['dispatch'],'#f97316'],['Waiting customer',$requestStageCounts['customer'],'#15a878'],['Completed',$requestStageCounts['closed'],'#dce6f1']];
    $workSegments = [['In progress',$inProgressCount,'#1682df'],['Overdue',$overdueCount,'#ef1741'],['Completed',$completedCount,'#16a878']];
    $assetSegments = [['Operational',$activeAssetCount,'#16a878'],['Maintenance',$maintenanceAssetCount,'#1682df'],['Requires attention',$criticalAssetCount,'#f4a51c'],['Stopped',$stoppedAssetCount,'#ef1741']];
    $donutGradient = function (array $segments): string { $total = max(1, array_sum(array_column($segments, 1))); $position = 0; $stops = []; foreach ($segments as [, $count, $color]) { if (!$count) continue; $next = $position + (($count / $total) * 100); $stops[] = $color.' '.$position.'% '.$next.'%'; $position = $next; } return $stops ? implode(',', $stops) : '#e8eef6 0 100%'; };
    $maxMonthly = max(1, $monthlyActivity->max('requests'), $monthlyActivity->max('work_orders'));
    $chartPoints = function (string $key) use ($monthlyActivity, $maxMonthly): string { return $monthlyActivity->values()->map(fn ($month, $index) => (10 + ($index * 20)).','.round(70 - (($month[$key] / $maxMonthly) * 58), 1))->implode(' '); };
    $recentActivity = collect($recentRequests)->map(fn ($request) => ['kind'=>'requests','title'=>'Service request created','reference'=>$request->request_no ?? ('Request #'.$request->id),'time'=>optional($request->created_at)->diffForHumans()])->concat(collect($recentWorkOrders)->map(fn ($workOrder) => ['kind'=>'work-orders','title'=>'Work order updated','reference'=>$workOrder->work_order_no ?? ('Work order #'.$workOrder->id),'time'=>optional($workOrder->updated_at)->diffForHumans()]))->take(3);
    $pendingApprovals = collect($quotations)->filter(fn ($quotation) => in_array(strtoupper((string) $quotation->status), ['SENT','UNDER_REVIEW','REVISION_REQUESTED']))->take(3);
