<script>
    (() => { const app = document.getElementById('customer-app'); const button = document.getElementById('sidebar-toggle'); if (!app || !button) return; const key = 'unifco-customer-sidebar-collapsed'; if (localStorage.getItem(key) === '1') app.classList.add('sidebar-collapsed'); const sync = () => { button.textContent = app.classList.contains('sidebar-collapsed') ? '⇥' : '⇤'; }; sync(); button.addEventListener('click', () => { app.classList.toggle('sidebar-collapsed'); localStorage.setItem(key, app.classList.contains('sidebar-collapsed') ? '1' : '0'); sync(); }); })();
</script>
